/* test_delegate_context_shed.c: unit tests for delegate prompt context shedding
 * and named-file drift detection */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include "aimee.h"
#include "cmd_agent_delegate_impl.h"
#include <aimee/delegates/delegate_launch_args.h>

/* The drift check narrows its hard-fail with the module's write-intent rule,
 * reached through delegate_prompt_asks_for_writes(). A C test cannot call the
 * module, so this provider serves the module's ANSWERS for the briefs below
 * -- generated by feeding each to delegates.PromptAllowsWrites -- rather than
 * restating a rule that now lives in exactly one place.
 *
 * Only the brief's half is consulted here, so the role argument is ignored.
 * An unlisted brief aborts: a new fixture has to ask the module, not guess. */
static const struct
{
   const char *prompt;
   int asks_for_writes;
} k_prompt_write_answers[] = {
    {"Create a new file src/newfile.c with the module.", 1},
    {"Edit done/full-autonomous-development.md to revise the plan.", 1},
    {"Edit src/nonexistent.c to fix the bug.", 1},
    {"Edit src/nonexistent_xyz.c to fix the bug.", 1},
    {"Edit the config parser to handle edge cases.", 1},
    {"Read isolated/context.c and summarize it without edits.", 1},
    {"Read-only review of src/newfile.c. Do not edit files.", 0},
    {"Review src/config.c. Do not edit files.", 0},
    {"Update /mnt/media/other/thing.c on the remote host.", 1},
    {"Update aimee-server on the host. The server config lives at "
     "admin@192.168.1.254:/mnt/media/.plugins/aimee-server/server/home/aimee.yaml; read it over "
     "SSH and confirm the bearer token.",
     1},
};

static int shed_test_may_write(const char *role, const char *prompt, int *may_write, int *by_role,
                               int *by_prompt)
{
   (void)role;
   if (by_role)
      *by_role = 1;
   if (!prompt || !prompt[0])
   {
      /* The module abstains on an empty brief -- it can only narrow, never
       * grant -- so the role's answer stands. */
      if (by_prompt)
         *by_prompt = 1;
      if (may_write)
         *may_write = 1;
      return 0;
   }
   for (size_t i = 0; i < sizeof(k_prompt_write_answers) / sizeof(k_prompt_write_answers[0]); i++)
      if (prompt && strcmp(k_prompt_write_answers[i].prompt, prompt) == 0)
      {
         if (by_prompt)
            *by_prompt = k_prompt_write_answers[i].asks_for_writes;
         if (may_write)
            *may_write = k_prompt_write_answers[i].asks_for_writes;
         return 0;
      }
   fprintf(stderr,
           "test_delegate_context_shed: no recorded module answer for prompt \"%s\".\n"
           "Ask delegates.PromptAllowsWrites for it and add the row; do not guess.\n",
           prompt ? prompt : "(null)");
   abort();
}

/* ---- helpers ---- */

static char g_tmpdir[256];

static void setup_tmpdir(void)
{
   snprintf(g_tmpdir, sizeof(g_tmpdir), "/tmp/test_dcs_XXXXXX");
   assert(mkdtemp(g_tmpdir) != NULL);
}

static void cleanup_tmpdir(void)
{
   char cmd[512];
   snprintf(cmd, sizeof(cmd), "rm -rf '%s'", g_tmpdir);
   (void)system(cmd);
}

static void make_file(const char *relpath)
{
   char path[512];
   snprintf(path, sizeof(path), "%s/%s", g_tmpdir, relpath);
   FILE *f = fopen(path, "w");
   assert(f != NULL);
   fprintf(f, "/* test file */\n");
   fclose(f);
}

